def main(apply: bool) -> None:
    init_db()
    conn = connect()
    try:
        before = conn.execute("SELECT COUNT(*) AS n FROM questions").fetchone()["n"]
        print(f"questions before: {before}")
        print(f"rows defined:     {len(QUESTIONS)}")

        if not apply:
            existing = {r["question"] for r in conn.execute("SELECT question FROM questions")}
            net_new = sum(1 for (q, *_) in QUESTIONS if q not in existing)
            print(f"net new (estimated): {net_new}")
            print("\nDRY RUN — no writes. Re-run with --apply to seed.")
            conn.close()
            return

        # Snapshot before writing.
        from eklavya.backups import snapshot
        snap_id = snapshot("before seed_questions_expansion --apply")
        print(f"\nSnapshot taken: {snap_id}")

        conn.executemany(
            "INSERT OR IGNORE INTO questions(question, topic, difficulty, role, company, source) "
            "VALUES(?, ?, ?, ?, ?, ?)",
            [(q, t, d or None, r or None, c or None, s or None)
             for (q, t, d, r, c, s) in QUESTIONS],
        )
        conn.commit()
        after = conn.execute("SELECT COUNT(*) AS n FROM questions").fetchone()["n"]
        print(f"questions after:  {after}  (+{after - before} new rows inserted)")
    finally:
        conn.close()


if __name__ == "__main__":
    main(apply="--apply" in sys.argv)
